const GOOGLE_TOKEN_URL='https://oauth2.googleapis.com/token';const CORS_HEADERS={'Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'POST,OPTIONS','Access-Control-Allow-Headers':'Content-Type',};function corsJson(obj,status){return new Response(JSON.stringify(obj),{status,headers:{'Content-Type':'application/json',...CORS_HEADERS},});}export default{async fetch(request,env){if(request.method==='OPTIONS'){return new Response(null,{status:204,headers:CORS_HEADERS});}if(request.method !=='POST'){return corsJson({error:'method_not_allowed'},405);}let body;try{body=await request.json();}catch{return corsJson({error:'invalid_request',error_description:'body 不是合法 JSON'},400);}const clientSecret=(env.GOOGLE_CLIENT_SECRET || '').trim();if(!clientSecret){return corsJson({error:'server_error',error_description:'Worker 没配 GOOGLE_CLIENT_SECRET'},500);}const clientId=String(body.client_id || '').trim();if(!clientId){return corsJson({error:'invalid_request',error_description:'缺 client_id'},400);}const grantType=String(body.grant_type || '');const params=new URLSearchParams();params.set('client_id',clientId);params.set('client_secret',clientSecret);if(grantType==='authorization_code'){const code=String(body.code || '');const redirectUri=String(body.redirect_uri || '');const verifier=String(body.code_verifier || '');if(!code || !redirectUri || !verifier){return corsJson({error:'invalid_request',error_description:'授权码流程缺 code / redirect_uri / code_verifier'},400);}params.set('grant_type','authorization_code');params.set('code',code);params.set('redirect_uri',redirectUri);params.set('code_verifier',verifier);}else if(grantType==='refresh_token'){const refreshToken=String(body.refresh_token || '');if(!refreshToken){return corsJson({error:'invalid_request',error_description:'缺 refresh_token'},400);}params.set('grant_type','refresh_token');params.set('refresh_token',refreshToken);}else{return corsJson({error:'unsupported_grant_type',error_description:'只支持 authorization_code / refresh_token'},400);}let upstream;try{upstream=await fetch(GOOGLE_TOKEN_URL,{method:'POST',headers:{'Accept':'application/json'},body:params,});}catch(e){return corsJson({error:'server_error',error_description:'连不上 Google token 接口：'+String((e && e.message)|| e || '')},502);}const text=await upstream.text();return new Response(text,{status:upstream.status,headers:{'Content-Type':'application/json',...CORS_HEADERS},});},};